const modules=new Set(['carteqr','scanner','pilotage','finance-direction','academy-direction','annuaire','bibliotheque','rendezvous','site-public','espace-soldat','adhesions','anniversaires','suivi-poles']);
const titles={carteqr:'Ma carte de présence',scanner:'Scanner & activités',pilotage:'Poste de commandement','finance-direction':'Finances & missions','academy-direction':'Gestion de la Soldiers Academy',annuaire:'Annuaire des membres',bibliotheque:'Bibliothèque & enseignements',rendezvous:'Événements & notifications','site-public':'Contenu du site public','espace-soldat':'Mon espace Soldat',adhesions:'Demandes d’adhésion',anniversaires:'Anniversaires des membres','suivi-poles':'Suivi des pôles'};
async function api(path,method='GET',body){const r=await fetch(path,{method,credentials:'same-origin',cache:'no-store',headers:{'content-type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.message||'Le service est indisponible. Réessayez.');return d}
const calm=()=>!!(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches||document.body?.dataset.motion==='paused');
/* Compteur animé : part de la dernière valeur affichée, jamais de zéro à chaque actualisation. */
function useCountUp(target,duration=950){
 const end=Number(target),ok=target!=null&&target!==''&&Number.isFinite(end),prev=useRef(0),[value,setValue]=useState(()=>ok&&!calm()?0:end);
 useEffect(()=>{if(!ok)return;if(calm()){prev.current=end;setValue(end);return}let raf=0,begin=0;const from=prev.current;const tick=t=>{if(!begin)begin=t;const p=Math.min(1,(t-begin)/duration);const v=from+(end-from)*(1-Math.pow(1-p,4));prev.current=v;setValue(v);if(p<1)raf=requestAnimationFrame(tick)};raf=requestAnimationFrame(tick);return()=>cancelAnimationFrame(raf)},[end,ok,duration]);
 return ok?value:target;
}
function Num({value,suffix=''}){const n=useCountUp(value);return typeof n==='number'?<>{Math.round(n).toLocaleString('fr-FR')}{suffix}</>:<>{value??'—'}</>}
const when=t=>{const n=Math.max(0,Math.floor((Date.now()-t)/60000));return n<1?'à l’instant':n<60?'il y a '+n+' min':'il y a '+Math.floor(n/60)+' h'};
const money=n=>new Intl.NumberFormat('fr-CI',{style:'currency',currency:'XOF',maximumFractionDigits:0}).format(Number(n)||0);
function Progress({done,total}){const shown=useCountUp(Math.min(total,done||0),1100);return total>0?<div className="ops-progress"><progress max={total} value={typeof shown==='number'?shown:0} aria-label={(done||0)+' sur '+total}/><span>{Math.round((done||0)/total*100)} % · {done||0} / {total}</span></div>:<p className="ops-muted">Aucune progression renseignée.</p>}
function useData(path,refresh=0){const [data,setData]=useState(null),[error,setError]=useState(''),[version,setVersion]=useState(0);useEffect(()=>{let live=true;setError('');api(path).then(d=>{if(live)setData(d)}).catch(e=>{if(live)setError(e.message)});return()=>{live=false}},[path,version]);useEffect(()=>{if(!refresh)return;const id=setInterval(()=>{if(!document.hidden)setVersion(n=>n+1)},refresh);return()=>clearInterval(id)},[refresh]);return {data,error,reload:()=>setVersion(n=>n+1)}}
function Loading({state,children}){return state.error?<div role="alert" className="ops-notice">{state.error} <button onClick={state.reload}>Réessayer</button></div>:!state.data?<div role="status" className="ops-skeleton" aria-label="Chargement des données"><span className="ref-visually-hidden">Chargement des données…</span><i/><i/><i/><i/></div>:children(state.data)}
function Card({title,children,className='',style}){return <section className={'ops-card '+className} style={style}><h3>{title}</h3>{children}</section>}
function NativeButton({portal,module,action,id,member,children}){return <button type="button" data-act={action} data-id={id} data-mid={member} onClick={()=>portal.selectionner(module)}>{children}</button>}
export function DataPlot({rows,series,title}){
 const canvas=useRef(null),[light,setLight]=useState(document.documentElement.dataset.theme==='light');
 useEffect(()=>{const observer=new MutationObserver(()=>setLight(document.documentElement.dataset.theme==='light'));observer.observe(document.documentElement,{attributes:true,attributeFilter:['data-theme']});return()=>observer.disconnect()},[]);
 useEffect(()=>{if(!rows.length||typeof CanvasRenderingContext2D==='undefined')return;let chart;try{chart=new Chart(canvas.current,{type:'line',data:{labels:rows.map(r=>r.label),datasets:series.map((s,i)=>({label:s.label,data:rows.map(r=>r[s.key]||0),borderColor:(light?['#947021','#176e85']:['#e9c56f','#65c2cf'])[i%2],backgroundColor:c=>{const col=(light?['#947021','#176e85']:['#e9c56f','#65c2cf'])[i%2],{ctx,chartArea}=c.chart;if(!chartArea)return col+'22';const g=ctx.createLinearGradient(0,chartArea.top,0,chartArea.bottom);g.addColorStop(0,col+(i%2?'40':'59'));g.addColorStop(1,col+'00');return g},pointBackgroundColor:(light?['#947021','#176e85']:['#e9c56f','#65c2cf'])[i%2],fill:true,tension:.4,pointRadius:2.5,pointHoverRadius:5,borderWidth:2}))},options:{responsive:true,maintainAspectRatio:false,animation:calm()?false:{duration:950,easing:'easeOutQuart'},interaction:{mode:'index',intersect:false},plugins:{legend:{display:false,labels:{color:light?'#42516a':'#ccd5e4'}},tooltip:{backgroundColor:light?'#ffffffee':'#0b1530f2',titleColor:light?'#7a5a12':'#e2c26a',bodyColor:light?'#1a2236':'#ffffff',borderColor:'#d4af3766',borderWidth:1,cornerRadius:10,padding:10,titleFont:{family:"'Saira Condensed','Arial Narrow',sans-serif",size:13},bodyFont:{family:"'Atkinson Hyperlegible',system-ui,sans-serif",size:12}}},scales:{x:{ticks:{color:light?'#53627b':'#b6bccb',font:{family:"'Atkinson Hyperlegible',system-ui,sans-serif",size:10}},grid:{display:false}},y:{beginAtZero:true,ticks:{color:light?'#53627b':'#b6bccb',font:{family:"'Atkinson Hyperlegible',system-ui,sans-serif",size:10}},grid:{color:'#78859c25'}}}}})}catch{}return()=>chart?.destroy()},[rows,series,light]);
 return <div className="ops-plot">{rows.length?<><div className="ops-canvas"><canvas ref={canvas} role="img" aria-label={title+' — données disponibles dans le tableau suivant'}/></div><details><summary>Consulter les données du graphique</summary><div className="ops-table-scroll"><table><caption>{title}</caption><thead><tr><th>Période</th>{series.map(s=><th key={s.key}>{s.label}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={i}><th>{r.label}</th>{series.map(s=><td key={s.key}>{r[s.key]||0}</td>)}</tr>)}</tbody></table></div></details></>:<div className="ref-empty-state"><RefIcon name="qr"/><strong>Les tendances commenceront au premier pointage</strong><p>Enregistrez une rencontre et les présences pour voir leur évolution ici.</p></div>}</div>
}
function CompactQr(){const state=useData('/api/ma-carte-qr');if(!state.data)return null;const qr=qrcode(0,'M');qr.addData(state.data.code,'Byte');qr.make();return <img className="member-live-qr" alt="" src={'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(qr.createSvgTag({cellSize:3,scalable:true}))}/>}
function PersonalQr({portal}){
 const state=useData('/api/ma-carte-qr'),[message,setMessage]=useState('');
 return <Loading state={state}>{d=>{const qr=qrcode(0,'M');qr.addData(d.code,'Byte');qr.make();const src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(qr.createSvgTag({cellSize:5,scalable:true}));return <><div className="ops-qr-card"><div className="ops-brand"><img src="/vitrine/logo-96.png" alt=""/><span>MOUVEMENT S.D.E.<small>CARTE DE PRÉSENCE</small></span></div><h3>{d.nom}</h3><p>{d.matricule||'Membre SDE'}</p><img className="ops-qr-image" src={src} alt="Mon QR Code personnel à présenter au responsable du pointage"/><p>Présentez ce QR au responsable à l’entrée de la rencontre.</p><small>À renouveler après le {new Date(d.expire).toLocaleString('fr-CI',{timeZone:'Africa/Abidjan'})}.</small><button onClick={async()=>{try{await navigator.clipboard.writeText(d.code);setMessage('Code copié. Vous pouvez le transmettre au responsable du pointage.')}catch{setMessage('La copie est indisponible sur cet appareil. Présentez le QR à l’écran.')}}}>Copier mon code de présence</button><p role="status">{message}</p></div><NativeButton portal={portal} module="espace">Mon profil et ma carte imprimable</NativeButton><p className="ops-muted">Le code identifie votre fiche. Gardez-le personnel et présentez-vous au responsable lors du contrôle.</p></>}}</Loading>
}
function Scanner(){
 const state=useData('/api/pointage-qr'),[event,setEvent]=useState(''),[code,setCode]=useState(''),[message,setMessage]=useState(''),[camera,setCamera]=useState(false),[busy,setBusy]=useState(false);
 const video=useRef(null),session=useRef(new CameraSession()),alive=useRef(true),working=useRef(false);
 const stop=()=>{session.current.stop();if(alive.current)setCamera(false)};
 useEffect(()=>()=>{alive.current=false;session.current.stop()},[]);
 async function record(value){if(working.current)return;working.current=true;setBusy(true);setMessage('Vérification de la carte…');try{const r=await api('/api/pointage-qr','POST',{evenement:event,code:value.trim()});if(alive.current){setMessage((r.deja?'Présence déjà enregistrée : ':'Présence enregistrée : ')+r.nom+' · '+r.rencontre);setCode('');state.reload()}}catch(e){if(alive.current)setMessage(e.message)}finally{working.current=false;if(alive.current)setBusy(false)}}
 async function start(){if(!event)return;setMessage('Autorisez la caméra pour lire une carte SDE.');setCamera(true);try{await session.current.start(async()=>{const {BrowserQRCodeReader}=await import('@zxing/browser');const reader=new BrowserQRCodeReader();return(stream,consume)=>reader.decodeFromStream(stream,video.current,(result,error,ctrl)=>{if(result){ctrl.stop();consume(result.getText())}})},()=>navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}}),value=>{if(alive.current){setCamera(false);void record(value)}})}catch{stop();if(alive.current)setMessage('Caméra indisponible ou autorisation refusée. Utilisez la saisie du code ci-dessous.')}}
 return <><p className="ops-muted">Choisissez la rencontre, puis scannez la carte ouverte dans l’espace du membre. Chaque présence est vérifiée et enregistrée sur le serveur.</p><Loading state={state}>{d=><div className="ref-scanner-grid"><Card title="Scanner de QR code" className="ref-scanner-camera"><div className={'ops-scanner-window '+(camera?'active':'')}><video ref={video} playsInline muted aria-label="Caméra de lecture des QR Codes"/><span aria-hidden="true" className="ops-scanner-frame"/>{!camera&&<p>La caméra s’active uniquement à votre demande.</p>}</div><div className="ops-actions"><button disabled={!event||busy||camera} onClick={start}>Activer le scanner</button><button disabled={!camera} onClick={stop}>Arrêter la caméra</button></div></Card><Card title="Pointage" className="ref-scanner-details"><label>Rencontre<select value={event} disabled={busy||camera} onChange={e=>setEvent(e.target.value)}><option value="">Choisir une rencontre passée ou du jour</option>{(d.evenements||[]).map(e=><option key={e.id} value={e.id}>{e.date} · {e.titre}</option>)}</select></label>{!d.evenements?.length&&<p>Aucune rencontre disponible. Créez une rencontre dans l’agenda avant de pointer.</p>}<form onSubmit={e=>{e.preventDefault();stop();void record(code)}}><label>Code SDE reçu ou lu par une douchette<textarea value={code} onChange={e=>setCode(e.target.value)} required maxLength={1200} rows={3} placeholder="SDE1.…"/></label><button disabled={!event||busy||!code.trim()}>{busy?'Enregistrement…':'Enregistrer la présence'}</button></form><h4>Activités récentes</h4><ul className="ops-list">{(d.activites||[]).map(a=><li key={a.id}><strong>{a.nom}</strong><span>{a.rencontre}</span><time>{new Date(a.cree).toLocaleString('fr-CI',{timeZone:'Africa/Abidjan'})}</time></li>)}</ul>{!d.activites?.length&&<p>Aucun pointage QR enregistré.</p>}</Card></div>}</Loading><p className="ops-notice" role="status" aria-live="polite">{message}</p></>
}
function Academy({portal}){const state=useData('/api/pilotage-academy');return <Loading state={state}>{d=><><div className="ops-kpis"><Card title="Inscriptions"><strong>{d.progression?.inscriptions||0}</strong></Card><Card title="Parcours certifiés"><strong>{d.progression?.certifies||0}</strong></Card><Card title="Dossiers à examiner"><strong>{d.prets?.length||0}</strong></Card><Card title="Présences en formation"><strong>{d.assiduite?.taux==null?'—':d.assiduite.taux+' %'}</strong><small>7 dernières rencontres de type Formation · actifs concernés</small></Card></div><div className="ops-grid"><Card title="Progression collective"><Progress done={d.progression?.modulesSuivis} total={d.progression?.modulesAttendus}/><p className="ops-muted">Modules renseignés par les formateurs, hors parcours retirés ou abandonnés.</p>{(d.formations||[]).map(f=><article className="ops-course" key={f.id}><h4>{f.titre}</h4><p>{f.inscrits} inscrit(s) · {f.certifies} certifié(s)</p><Progress done={f.faits} total={f.total}/><NativeButton portal={portal} module="academie" action="voir-formation" id={f.id}>Gérer cette formation</NativeButton></article>)}</Card><Card title="Élèves prêts à valider"><p className="ops-muted">Tous les modules sont suivis. La certification reste à examiner dans le dossier du participant.</p><ul className="ops-list">{(d.prets||[]).map(p=><li key={p.formation+p.membre}><strong>{p.nom}</strong><span>{p.titre} · {p.faits}/{p.total} modules</span><NativeButton portal={portal} module="academie" action="voir-participant" id={p.formation} member={p.membre}>Examiner et valider</NativeButton></li>)}</ul>{!d.prets?.length&&<p>Aucun dossier complet en attente de certification.</p>}</Card></div><NativeButton portal={portal} module="academie">Toutes les formations et attestations</NativeButton></>}</Loading>}
function Finance({portal}){const state=useData('/api/pilotage-finances'),[period,setPeriod]=useState(12),[message,setMessage]=useState(''),[busy,setBusy]=useState('');async function approve(p){setBusy(p.id);try{await api('/api/budget-validation','POST',{projet:p.id,montant:p.budget});setMessage('Budget validé pour '+p.titre+'. Aucun paiement n’a été effectué.');state.reload()}catch(e){setMessage(e.message)}finally{setBusy('')}}return <Loading state={state}>{d=><><p className="ops-muted">Du {d.depuis} au {d.jusquau} · FCFA · Les mouvements annulés sont exclus.</p><div className="ops-kpis"><Card title="Entrées de caisse"><strong>{money(d.entrees)}</strong></Card><Card title="Sorties de caisse"><strong>{money(d.sorties)}</strong></Card><Card title="Flux net sur 12 mois"><strong>{money(d.entrees-d.sorties)}</strong><small>Entrées moins sorties ; ne constitue pas le solde bancaire.</small></Card></div><Card title="Évolution mensuelle de la caisse"><label>Période du graphique<select value={period} onChange={e=>setPeriod(Number(e.target.value))}>{[3,6,12].map(n=><option key={n} value={n}>{n} derniers mois</option>)}</select></label><DataPlot title="Mouvements de caisse en FCFA" rows={d.avecOperations?(d.mensuel||[]).slice(-period).map(r=>({...r,label:r.mois})):[]} series={[{key:'entrees',label:'Entrées'},{key:'sorties',label:'Sorties'}]}/></Card><div className="ops-grid"><Card title="Offrandes, dîmes et contributions"><p className="ops-muted">Registre des offrandes sur la même période. Ces montants peuvent déjà figurer en caisse ; ils ne sont pas ajoutés aux entrées ci-dessus.</p><ul className="ops-list">{(d.offrandes||[]).map(r=><li key={r.titre}><strong>{r.titre}</strong><span>{money(r.montant)}</span></li>)}</ul>{!d.offrandes?.length&&<p>Aucune offrande renseignée.</p>}</Card><Card title="Contributions par pôle"><p className="ops-muted">Pôle enregistré sur le versement, ou pôle actuel du membre lorsqu’il est lié au versement.</p><ul className="ops-list">{(d.poles||[]).map(r=><li key={r.titre}><strong>{r.titre}</strong><span>{money(r.montant)}</span></li>)}</ul>{!d.poles?.length&&<p>Aucune contribution répartie par pôle.</p>}</Card></div><Card title="Pôles & missions — budgets et équipes"><div className="ops-table-scroll"><table><thead><tr><th>Mission</th><th>Budget prévu</th><th>Dépensé sur 12 mois</th><th>Équipe engagée</th><th>Avancement</th><th>Validation</th></tr></thead><tbody>{(d.projets||[]).map(p=><tr key={p.id}><th>{p.titre}<small>{p.statut}</small></th><td>{money(p.budget)}</td><td>{money(p.depense)}</td><td>{p.engages}/{p.equipe}<small>Membres avec tâche en cours ou terminée</small></td><td><Progress done={p.faits} total={p.total}/></td><td>{p.valide?<span className="ops-badge">Budget validé</span>:p.budget>0?<button disabled={!!busy} onClick={()=>approve(p)}>Valider {money(p.budget)}</button>:'Budget non défini'}<NativeButton portal={portal} module="projets" action="voir-projet" id={p.id}>Dossier</NativeButton></td></tr>)}</tbody></table></div>{!d.projets?.length&&<p>Aucune mission enregistrée.</p>}</Card><p role="status">{message}</p><NativeButton portal={portal} module="finances">Ouvrir le registre détaillé et saisir une opération</NativeButton></>}</Loading>}
