function Adhesions({portal}){
 const [rows,setRows]=useState(null),[error,setError]=useState(''),[filter,setFilter]=useState('attente'),[busy,setBusy]=useState(0),[message,setMessage]=useState('');
 useEffect(()=>{let live=true;api('/api/engager-admin?limite=200').then(d=>{if(live)setRows(d.engagements||[])}).catch(e=>{if(live)setError(e.message||'Accès réservé à l’équipe administrative.')});return()=>{live=false}},[]);
 async function decide(r,traite,note){setBusy(r.id);setMessage('');try{await api('/api/engager-admin','PATCH',{id:r.id,traite,note});setRows(list=>list.map(x=>x.id===r.id?{...x,traite:traite?1:0,note}:x));setMessage(traite?'Les modifications ont été enregistrées.':'Demande remise à traiter.')}catch{setMessage('Cette action n’a pas pu être effectuée. Vérifiez les informations et réessayez.')}finally{setBusy(0)}}
 const day=t=>new Date(Number(t)).toLocaleDateString('fr-FR',{day:'numeric',month:'short',year:'numeric'});
 const tel=v=>String(v||'').replace(/[^\d+]/g,'');
 if(error)return <p role="alert" className="ops-notice">{error}</p>;
 if(!rows)return <p role="status" className="ops-skeleton">Chargement…</p>;
 const list=rows.filter(r=>filter==='toutes'||(filter==='attente'?!r.traite:!!r.traite));
 return <><p className="ops-muted">Consultez les demandes reçues, vérifiez les informations et assurez leur suivi. Après approbation, l’administrateur peut créer ou activer l’accès du membre.</p>
  <div className="ops-filters" role="group" aria-label="Filtrer les demandes">{[['attente','À traiter'],['traitees','Traitées'],['toutes','Toutes']].map(([k,l])=><button key={k} type="button" aria-pressed={filter===k} onClick={()=>setFilter(k)}>{l}</button>)}</div>
  <div className="ops-table-scroll"><table><thead><tr><th>Nom</th><th>Date de réception</th><th>Ville</th><th>Pôle souhaité</th><th>Programme souhaité</th><th>Statut</th><th>Action</th></tr></thead><tbody>{list.map(r=><tr key={r.id}><th>{r.nom}<small>{r.objet}</small></th><td>{day(r.cree)}</td><td>{r.ville||'—'}</td><td>{r.pole||'—'}</td><td>{(r.message||'').slice(0,80)||'—'}</td><td>{r.traite?(r.note||'Traitée'):'À traiter'}</td><td className="ops-actions">{r.tel&&<a href={'tel:'+tel(r.tel)}>Contacter</a>}{r.email&&<a href={'mailto:'+r.email}>E-mail</a>}{!r.traite?<><button type="button" disabled={busy===r.id} onClick={()=>decide(r,true,'Approuvée')}>Approuver</button><button type="button" disabled={busy===r.id} onClick={()=>decide(r,true,'Refusée')}>Refuser</button></>:<button type="button" disabled={busy===r.id} onClick={()=>decide(r,false,'')}>Remettre à traiter</button>}</td></tr>)}</tbody></table></div>
  {!list.length&&<p className="ops-muted">Aucun élément ne correspond actuellement à cette rubrique.</p>}<p role="status" aria-live="polite">{message}</p></>
}
const MONTHS=['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre'];
function parseBirthday(v){const t=String(v||'').trim();let m=t.match(/^(\d{4})-(\d{2})-(\d{2})/);if(m)return{d:+m[3],m:+m[2]};m=t.match(/^(\d{1,2})[\/.-](\d{1,2})(?:[\/.-]\d{2,4})?$/);return m&&+m[2]>=1&&+m[2]<=12&&+m[1]>=1&&+m[1]<=31?{d:+m[1],m:+m[2]}:null}
function Birthdays(){
 const state=useData('/api/annuaire-portail'),[month,setMonth]=useState(0);
 return <Loading state={state}>{d=>{
  const today=new Date(),y=today.getFullYear(),start=new Date(y,today.getMonth(),today.getDate());
  const all=(d.membres||[]).filter(x=>x.actif).map(x=>({...x,b:parseBirthday(x.anniv)})).filter(x=>x.b).map(x=>{let next=new Date(y,x.b.m-1,x.b.d);if(next<start)next=new Date(y+1,x.b.m-1,x.b.d);return{...x,next,days:Math.round((next-start)/86400000)}}).sort((a,b)=>a.next-b.next);
  const shown=month?all.filter(x=>x.b.m===month):all.filter(x=>x.days<=30);
  const missing=(d.membres||[]).filter(x=>x.actif).length-all.length;
  return <><p className="ops-muted">Retrouvez les anniversaires à venir et préparez un message ou une attention au nom du Mouvement SDE. Les dates restent réservées aux personnes autorisées.</p>
   <label>Mois<select value={month} onChange={e=>setMonth(Number(e.target.value))}><option value={0}>30 prochains jours</option>{MONTHS.map((n,i)=><option key={n} value={i+1}>{n}</option>)}</select></label>
   <div className="ops-table-scroll"><table><thead><tr><th>Nom et prénoms</th><th>Date d’anniversaire</th><th>Pôle</th><th>Dans</th></tr></thead><tbody>{shown.map(x=><tr key={x.id}><th>{x.nom}<small>{x.matricule}</small></th><td>{x.b.d} {MONTHS[x.b.m-1]}</td><td>{x.pole||'—'}</td><td>{x.days===0?'Aujourd’hui':x.days+' j'}</td></tr>)}</tbody></table></div>
   {!shown.length&&<p className="ops-muted">Aucun élément ne correspond actuellement à cette rubrique.</p>}
   {missing>0&&<p className="ops-muted">{missing} fiche(s) sans date d’anniversaire exploitable.</p>}</>}}</Loading>
}
const POLES=[['Réveil, évangélisation & missions',/r[ée]veil|[ée]vang|mission/i,'Activités · Présences'],['Impact social & humanitaire',/impact|social|humanitaire/i,'Actions solidaires · Besoins suivis'],['Logistique & organisation',/logisti|organisation/i,'Matériel · Préparation des activités'],['Communication, médias & digital',/communication|m[ée]dia|digital/i,'Annonces · Supports publiés'],['Formation & développement intégral',/formation|d[ée]veloppement/i,'Parcours · Ressources disponibles']];
function PoleTracking({portal}){
 const state=useData('/api/annuaire-portail');
 return <Loading state={state}>{d=>{
  const members=(d.membres||[]).filter(x=>x.actif);
  const rows=POLES.map(([name,re,detail],i)=>{const m=members.filter(x=>re.test(x.pole||''));const lead=m.filter(x=>/responsable|leader|chef/i.test(x.fonction||'')).map(x=>x.nom);const rates=m.map(x=>x.presence).filter(v=>typeof v==='number');return{name,detail,num:String(i+1).padStart(2,'0'),count:m.length,lead,rate:rates.length?Math.round(rates.reduce((a,b)=>a+b,0)/rates.length):null}});
  const other=members.length-rows.reduce((n,r)=>n+r.count,0);
  return <><p className="ops-muted">Effectif, responsable et présence moyenne de chacun des cinq pôles, d’après les fiches des membres actifs.</p>
   <div className="ops-grid">{rows.map(r=><Card key={r.name} title={r.num+' — '+r.name}><ul className="ops-list"><li><strong>Effectif</strong><span><Num value={r.count}/></span></li><li><strong>Responsable</strong><span>{r.lead.join(', ')||'À renseigner'}</span></li><li><strong>Présence moyenne</strong><span>{r.rate==null?'—':r.rate+' %'}</span></li></ul><p className="ops-muted">{r.detail}</p><NativeButton portal={portal} module="annuaire">Voir les membres</NativeButton></Card>)}</div>
   {other>0&&<p className="ops-muted">{other} membre(s) actif(s) sans pôle correspondant aux cinq pôles.</p>}</>}}</Loading>
}
